package app.swtv.home.ui
import android.app.AlertDialog
import android.widget.EditText
import app.swtv.home.MainActivity
import app.swtv.home.core.*
class SettingsController(private val a:MainActivity) {
 private val c get()=a.config
 fun show(){options("Settings",listOf("Dock slots & order","Grid columns: ${c.columns}","Theme: ${c.theme}","Accent: ${c.accent}","Reduced motion: ${c.reducedMotion}","Phone apps: ${c.showPhoneApps}","Unhide apps","Custom modules","Wallpaper","Weather","OwnTV target","Reset configuration")){when(it){0->options("Dock slots",(1..6).map{"Slot $it"}){dockSlot(it)};1->options("Grid columns",(3..8).map{it.toString()}){a.save(c.copy(columns=it+3))};2->options("Theme",listOf("auto","light","dark")){a.save(c.copy(theme=listOf("auto","light","dark")[it]))};3->options("Accent",listOf("cyan","violet","blue","green","amber","rose")){a.save(c.copy(accent=listOf("cyan","violet","blue","green","amber","rose")[it]))};4->a.save(c.copy(reducedMotion=!c.reducedMotion));5->a.save(c.copy(showPhoneApps=!c.showPhoneApps));6->unhide();7->modules();8->options("Wallpaper",listOf("Built-in time gradient","Choose image")){if(it==0)a.save(c.copy(wallpaperUri=""))else a.pickWallpaper()};9->weather();10->iptv();11->AlertDialog.Builder(a).setTitle("Reset all local configuration?").setPositiveButton("Reset"){_,_->a.save(LauncherConfig())}.setNegativeButton("Cancel",null).show()}}}
 private fun options(title:String,items:List<String>,choose:(Int)->Unit){if(items.isEmpty()){a.notice(title,"No available choices on this device.");return};AlertDialog.Builder(a).setTitle(title).setItems(items.toTypedArray()){_,i->choose(i)}.setNegativeButton("Cancel",null).show()}
 private fun edit(title:String,value:String,done:(String)->Unit){val field=EditText(a).apply{setText(value);isSingleLine=true;selectAll()};AlertDialog.Builder(a).setTitle(title).setView(field).setPositiveButton("Save"){_,_->done(field.text.toString().trim())}.setNegativeButton("Cancel",null).show();field.requestFocus()}
 fun dockSlot(index:Int){val pkg=c.dock.getOrNull(index);options("Dock slot ${index+1}",listOf("Choose / swap app","Move left","Move right","Clear slot")){when(it){0->options("Choose dock app",a.apps.map{it.label}){selected->val next=a.apps[selected].packageName;val pins=c.dock.toMutableList();val old=pins.getOrNull(index);val existing=pins.indexOf(next);if(existing>=0 && old!=null){pins[existing]=old;pins[index]=next}else {pins.remove(next);pins.add(index.coerceAtMost(pins.size),next)};a.save(c.copy(dock=pins.take(6)))};1,2->if(pkg!=null)a.save(c.copy(dock=CatalogRules.movePin(c.dock,pkg,index+if(it==1)-1 else 1)));3->if(pkg!=null)a.save(c.copy(dock=c.dock-pkg))}}}
 private fun unhide(){val hidden=c.hidden.sorted();options("Unhide apps",listOf("Unhide all")+hidden.map{pkg->a.apps.firstOrNull{it.packageName==pkg}?.label ?: pkg}){if(it==0)a.save(c.copy(hidden=emptySet()))else a.save(c.copy(hidden=c.hidden-hidden[it-1]))}}
 private fun modules(){options("Custom modules",listOf("Add app shortcut","Add input shortcut")+c.modules.map{it.label}){when(it){0->{if(c.modules.size>=8){a.notice("Module limit","Remove a module before adding another.");return@options};options("Installed app",a.apps.map{it.label}){i->val app=a.apps[i];edit("Shortcut label",app.label){label->a.save(c.copy(modules=c.modules+ModuleTile(label,app.packageName,"app")))}}};1->{if(c.modules.size>=8){a.notice("Module limit");return@options};options("Discovered input",a.inputs.map{it.label}){i->val input=a.inputs[i];edit("Shortcut label",input.label){label->a.save(c.copy(modules=c.modules+ModuleTile(label,input.id,"input")))}}};else->moduleMenu(it-2)}}}
 fun moduleMenu(index:Int){val module=c.modules.getOrNull(index) ?: return;options(module.label,listOf("Rename","Remove")){if(it==1)a.save(c.copy(modules=c.modules.filterIndexed{i,_->i!=index})) else edit("Shortcut label",module.label){label->a.save(c.copy(modules=c.modules.mapIndexed{i,m->if(i==index)m.copy(label=label) else m}))}}}
 fun iptv(){options("OwnTV · Choose installed app",a.apps.map{it.label+" · "+it.packageName}){a.save(c.copy(iptvPackage=a.apps[it].packageName))}}
 private fun weather(){options("Weather · Open-Meteo",listOf("City: ${c.weatherCity.ifBlank{"not set"}}",if(c.weatherEnabled)"Disable weather" else "Enable weather")){if(it==0)edit("Weather city (no location permission)",c.weatherCity){a.save(c.copy(weatherCity=it,weatherEnabled=c.weatherEnabled && it.isNotBlank()))}else if(!c.weatherEnabled && c.weatherCity.isBlank())a.notice("Choose a city first","Set your city, then explicitly enable weather.")else a.save(c.copy(weatherEnabled=!c.weatherEnabled))}}
}
